/**
 * / Execute a query written in the supported Cypher subset.
 * /
 * / The Cypher string is parsed and compiled to the internal Datalog IR, then
 * / evaluated by the same engine as the `Query` RPC. Returns bindings for the
 * / variables named in the RETURN clause (filtered to those variable names).
 * / When the RETURN clause contains aggregate functions (count(*), collect(), etc.),
 * / aggregate values appear in the `values` map of each CypherBinding row.
 */
export interface CypherQueryRequest {
  /**
   * / Cypher query string, e.g.:
   * /   MATCH (a:Person)-[:knows]->(b:Person)
   * /   WHERE a.name = "Alice"
   * /   RETURN a, count(*) AS n
   * /   ORDER BY n DESC
   * /   SKIP 0 LIMIT 10
   */
  cypher: string;
  /**
   * / Valid-time point-in-time filter (unix microseconds). 0 = now (current
   * / state; deleted/closed triples are hidden). Past timestamp = time-travel.
   */
  asOfValidTime: number;
  /** / Transaction-time snapshot override (unix microseconds). 0 = latest. */
  asOfTxTime: number;
  /**
   * / Query embedding vector for VECTOR_NEAR. Required when the Cypher string
   * / contains VECTOR_NEAR(var, "space", k) in the WHERE clause; ignored otherwise.
   */
  vector: number[];
  /** / HNSW exploration factor for VECTOR_NEAR. 0 = use server default. */
  ef: number;
  /** / Optional open-transaction ID. Reads from the transaction's snapshot. */
  txId: string;
  /** / Optional identity for access-control filtering. */
  userId: string;
  /**
   * / Named query parameters for `$param` substitution. Keys are parameter names
   * / (without the `$`); values are JSON-encoded `Value` objects.
   */
  params: { [key: string]: string };
  /**
   * / Dataset: graph IRIs the MATCH patterns read (unknown IRIs match
   * / nothing). Empty = every graph. A `USE GRAPH` clause takes precedence.
   */
  graphs: string[];
  /**
   * / Leave out inferred facts (the `urn:pg:inferred:*` graphs written by
   * / OWL RL inference); by default they are included.
   */
  excludeInferred: boolean;
}

export interface CypherQueryRequest_ParamsEntry {
  key: string;
  value: string;
}

/**
 * / One result row from a CypherQuery.
 * /
 * / For plain RETURN (no aggregations) `nodes` carries all bound variables and
 * / `values` is empty.  When RETURN contains aggregate functions, `nodes` carries
 * / the group-key variables and `values` carries the computed aggregates
 * / (e.g. count(*) AS n → `values["n"] = {int_val: 5}`).
 */
export interface CypherBinding {
  /** / Graph-node variable bindings (RETURN a, b). */
  nodes: { [key: string]: NodeId };
  /** / Scalar and aggregate variable bindings (count(*) AS n, collect(b) AS bs). */
  values: { [key: string]: Value };
}

export interface CypherBinding_NodesEntry {
  key: string;
  value?: NodeId | undefined;
}

export interface CypherBinding_ValuesEntry {
  key: string;
  value?: Value | undefined;
}

/** / Response from CypherQuery. */
export interface CypherQueryResponse {
  rows: CypherBinding[];
}

/** / Execute a Cypher write statement (CREATE, MERGE, SET, DELETE). */
export interface CypherWriteRequest {
  /**
   * / Cypher write string, e.g.:
   * /   CREATE (a:Person {name: "Alice"})
   * /   MERGE (c:Company {name: "Acme"})
   * /   SET a.active = true
   * /   DELETE a
   */
  cypher: string;
  /**
   * / Optional open-transaction ID. When set, writes are buffered into the
   * / named transaction rather than auto-committed.
   */
  txId: string;
  /**
   * / Graph IRI to write to and to MATCH in (interned on first use), as
   * / `USE GRAPH <iri>`. Empty = the default graph for writes and every
   * / graph for MATCH / MERGE / DELETE.
   */
  graph: string;
  /**
   * / Caller identity (optional; also `x-polargraph-user-id`). When set, the
   * / graph ACL applies — see docs/design/graph-acl.md.
   */
  userId: string;
}

export interface CypherWriteResponse {
  /** / UUIDs (16-byte NodeId) of nodes created by this statement (in order). */
  createdNodeIds: Buffer[];
  /** / Total number of property/relation triples inserted. */
  triplesWritten: number;
  /** / Total number of triples logically deleted (vt_end closed). */
  triplesDeleted: number;
}

/** / Static execution plan for a query, as returned by ExplainQuery. */
export interface ExplainResponse {
  /** / Human-readable plan summary (multi-line text). */
  planText: string;
  /** / One node per top-level plan step. */
  nodes: PlanNode[];
}

/** / A single node in the query execution plan tree. */
export interface PlanNode {
  /** / Node kind: "PatternScan", "RecursiveJoin", or "VectorSearch". */
  nodeType: string;
  /** / Human-readable description of this step. */
  description: string;
  /** / Column family used for the scan (e.g. "SPO", "POS", "OSP", "full scan"). */
  indexUsed: string;
  /** / Child nodes (e.g. body patterns of a RecursiveJoin). */
  children: PlanNode[];
}

