export interface PolarGraphServiceServer extends UntypedServiceImplementation {
  /** / Add to counters (service calls, primary only). */
  incrementCounters: handleUnaryCall<IncrementCountersRequest, IncrementCountersResponse>;
  /** / Read counters (service calls). */
  getCounters: handleUnaryCall<GetCountersRequest, GetCountersResponse>;
  /** / The vocabulary base, prefixes and legacy-conversion status. */
  getVocabulary: handleUnaryCall<GetVocabularyRequest, Vocabulary>;
  /** / Set the base IRI for bare names. */
  setVocabularyBase: handleUnaryCall<SetVocabularyBaseRequest, Vocabulary>;
  /** / Declare or re-point a prefix. */
  putPrefix: handleUnaryCall<PutPrefixRequest, Vocabulary>;
  /** / Remove a prefix (no-op if absent). */
  removePrefix: handleUnaryCall<RemovePrefixRequest, Vocabulary>;
  /**
   * / One-time conversion of pre-vocabulary data: bare predicates → IRIs,
   * / `__type` labels → `rdf:type`. Idempotent and resumable.
   */
  convertLegacyData: handleUnaryCall<ConvertLegacyDataRequest, ConvertLegacyDataResponse>;
  /**
   * / Insert one or more triples in a single atomic transaction.
   * / Returns ABORTED if a write-write conflict is detected.
   */
  insert: handleUnaryCall<InsertRequest, InsertResponse>;
  /** / Map node IDs back to IRIs via the IRI dictionary. */
  resolveIris: handleUnaryCall<ResolveIrisRequest, ResolveIrisResponse>;
  /** / Register a named graph (idempotent) and set its metadata. */
  createGraph: handleUnaryCall<CreateGraphRequest, CreateGraphResponse>;
  /** / List named graphs with their metadata, optionally filtered. */
  listGraphs: handleUnaryCall<ListGraphsRequest, ListGraphsResponse>;
  /** / Live-quad count and last write time of one graph. */
  graphStats: handleUnaryCall<GraphStatsRequest, GraphStatsResponse>;
  /** / Copy a graph's live quads into another graph (COPY / ADD semantics). */
  copyGraph: handleUnaryCall<CopyGraphRequest, CopyGraphResponse>;
  /** / Copy into the target (replacing it), then drop the source. */
  moveGraph: handleUnaryCall<MoveGraphRequest, CopyGraphResponse>;
  /** / Close every live quad of a graph (bitemporal tombstones). */
  dropGraph: handleUnaryCall<DropGraphRequest, DropGraphResponse>;
  /** / Stream the live quads of one graph, or of the whole dataset. */
  exportGraph: handleServerStreamingCall<ExportGraphRequest, ExportGraphChunk>;
  /** / Apply adds and retractions across graphs atomically. */
  applyChanges: handleUnaryCall<ApplyChangesRequest, ApplyChangesResponse>;
  /** / Validate a dataset (optionally with uncommitted changes) against SHACL shapes. */
  validateShapes: handleUnaryCall<ValidateShapesRequest, ValidateShapesResponse>;
  /** / Stream committed changes (with resume), filtered by graph access. */
  subscribe: handleServerStreamingCall<SubscribeRequest, ChangeEvent>;
  /** / Grant a user or group a level on a named graph. */
  grantGraphAccess: handleUnaryCall<GrantGraphAccessRequest, GrantGraphAccessResponse>;
  /** / Revoke a user's or group's grant on a named graph. */
  revokeGraphAccess: handleUnaryCall<RevokeGraphAccessRequest, RevokeGraphAccessResponse>;
  /** / A user's effective graph access. */
  getGraphAccess: handleUnaryCall<GetGraphAccessRequest, GetGraphAccessResponse>;
  /** / Execute a conjunctive query and return all satisfying variable bindings. */
  query: handleUnaryCall<QueryRequest, QueryResponse>;
  /** / Insert or update a node's embedding vector in the HNSW index. */
  insertVector: handleUnaryCall<InsertVectorRequest, InsertVectorResponse>;
  /** / Search for the k nearest neighbors of a query vector. */
  searchVector: handleUnaryCall<SearchVectorRequest, SearchVectorResponse>;
  /**
   * / Return all nodes transitively reachable from `start` via `predicate`.
   * / max_hops = 0 means unlimited depth.
   */
  reachable: handleUnaryCall<ReachableRequest, ReachableResponse>;
  /** / Register (or overwrite) a node type schema. */
  registerNodeType: handleUnaryCall<RegisterNodeTypeRequest, RegisterNodeTypeResponse>;
  /**
   * / Look up a registered node type by name. Returns an empty definition if
   * / the type does not exist.
   */
  getNodeType: handleUnaryCall<GetNodeTypeRequest, GetNodeTypeResponse>;
  /** / Return all registered node type schemas. */
  listNodeTypes: handleUnaryCall<ListNodeTypesRequest, ListNodeTypesResponse>;
  /**
   * / Validate a property map against a registered schema.
   * / Returns valid=false and a list of error messages on failure.
   */
  validateNode: handleUnaryCall<ValidateNodeRequest, ValidateNodeResponse>;
  /** / Register (or overwrite) an edge type schema. */
  registerEdgeType: handleUnaryCall<RegisterEdgeTypeRequest, RegisterEdgeTypeResponse>;
  /** / Look up a registered edge type by predicate name. */
  getEdgeType: handleUnaryCall<GetEdgeTypeRequest, GetEdgeTypeResponse>;
  /** / Return all registered edge type schemas. */
  listEdgeTypes: handleUnaryCall<ListEdgeTypesRequest, ListEdgeTypesResponse>;
  /** / Validate an edge's endpoint types and property map against a schema. */
  validateEdge: handleUnaryCall<ValidateEdgeRequest, ValidateEdgeResponse>;
  /**
   * / Return all registered predicate names whose domain and range match
   * / the supplied node type names. Unconstrained slots match any type.
   */
  listPredicatesBetween: handleUnaryCall<ListPredicatesBetweenRequest, ListPredicatesBetweenResponse>;
  /**
   * / Check the full ontology for consistency:
   * / - cardinality violations across all committed triples
   * / - missing inverse-predicate counterparts
   * / - cycles in the node type hierarchy (should not occur if RegisterNodeType
   * /   enforcement is in place, but this double-checks the live data)
   */
  validateOntology: handleUnaryCall<ValidateOntologyRequest, ValidateOntologyResponse>;
  /**
   * / Vector search with a node-type or reachability filter.
   * / Runs HNSW with a large candidate pool then post-filters to the allowed set.
   */
  searchVectorFiltered: handleUnaryCall<SearchVectorFilteredRequest, SearchVectorFilteredResponse>;
  /** / Score an explicit set of node IDs against a query vector; return top-k. */
  searchVectorInSet: handleUnaryCall<SearchVectorInSetRequest, SearchVectorInSetResponse>;
  /** / Insert multiple vectors into a named space atomically. */
  batchInsertVectors: handleUnaryCall<BatchInsertVectorsRequest, BatchInsertVectorsResponse>;
  /**
   * / Run an ANN vector search and use the results as seed bindings for a
   * / conjunctive Datalog query. Returns scored binding rows that satisfy
   * / both the vector similarity criterion and all graph patterns.
   */
  vectorSeedQuery: handleUnaryCall<VectorSeedQueryRequest, VectorSeedQueryResponse>;
  /**
   * / Create a new incremental backup of the live store.
   * / Returns FAILED_PRECONDITION if the server was not started with --backup-dir.
   */
  createBackup: handleUnaryCall<CreateBackupRequest, CreateBackupResponse>;
  /**
   * / List all available backups with ID, timestamp, size, and file count.
   * / Returns FAILED_PRECONDITION if the server was not started with --backup-dir.
   */
  listBackups: handleUnaryCall<ListBackupsRequest, ListBackupsResponse>;
  /**
   * / Delete all but the keep_n most recent backups.
   * / Returns FAILED_PRECONDITION if the server was not started with --backup-dir.
   * / Note: restore is an offline operation — see docs/architecture.md.
   */
  purgeOldBackups: handleUnaryCall<PurgeOldBackupsRequest, PurgeOldBackupsResponse>;
  /**
   * / Scan all hexastore column families and delete superseded versions (and
   * / triples whose valid-time windows have fully expired) per the policy.
   * / Triggers a full RocksDB compaction on any CF that had deletions.
   */
  runRetention: handleUnaryCall<RunRetentionRequest, RunRetentionResponse>;
  /**
   * / Return replication status for this server instance.
   * / `is_replica` is false and all other fields are zero/empty on the primary.
   */
  replicaStatus: handleUnaryCall<ReplicaStatusRequest, ReplicaStatusResponse>;
  /**
   * / Stream WAL entries from the primary. Returns FAILED_PRECONDITION on a replica.
   * / The stream runs indefinitely until the client disconnects; new entries are
   * / delivered within ~50 ms of commit.
   */
  streamWal: handleServerStreamingCall<StreamWalRequest, WalEntry>;
  /**
   * / Return the static execution plan for a query without running it.
   * / No database access is performed — pure static analysis of index selection.
   */
  explainQuery: handleUnaryCall<QueryRequest, ExplainResponse>;
  /**
   * / Apply any pending schema migrations and return the list of versions run.
   * / When dry_run is true, reports what would be applied without making changes.
   * / Returns FAILED_PRECONDITION on a read replica.
   */
  migrateSchema: handleUnaryCall<MigrateRequest, MigrateResponse>;
  /**
   * / Return the current and latest migration version, plus the full history
   * / of applied migrations with timestamps.
   */
  migrationStatus: handleUnaryCall<MigrationStatusRequest, MigrationStatusResponse>;
  /**
   * / Parse and execute a Cypher query string. Supports a subset of openCypher:
   * / MATCH, WHERE (= only), RETURN, LIMIT; directed relationships; transitive
   * / closure with [:pred*] or [:pred*min..max].
   * / Returns INVALID_ARGUMENT if the Cypher string cannot be parsed or contains
   * / write clauses (CREATE/MERGE/SET/DELETE) — use CypherWrite for mutations.
   */
  cypherQuery: handleUnaryCall<CypherQueryRequest, CypherQueryResponse>;
  /**
   * / DEPRECATED — removed in the next release; write with ApplyChanges or
   * / SPARQL Update (docs/upgrade-cypher-rdf.md). Responses carry a
   * / `warning` header.
   * / Parse and execute a Cypher write statement (CREATE, MERGE, SET, DELETE).
   * / Executes atomically in a single MVCC transaction.
   * / Returns INVALID_ARGUMENT if the statement cannot be parsed or contains no
   * / write clause. Returns FAILED_PRECONDITION on a read replica.
   */
  cypherWrite: handleUnaryCall<CypherWriteRequest, CypherWriteResponse>;
  /**
   * / Like `Query` but streams results in chunks of up to 500 bindings each.
   * / Use for large result sets that would otherwise exceed memory or message-size
   * / limits. The final chunk has `done = true`.
   */
  queryStream: handleServerStreamingCall<QueryRequest, QueryStreamChunk>;
  /**
   * / Like `CypherQuery` but streams results in chunks. Respects the LIMIT clause
   * / in the Cypher string. The final chunk has `done = true`.
   */
  cypherQueryStream: handleServerStreamingCall<CypherQueryRequest, QueryStreamChunk>;
  /** / Return per-column-family key counts and sizes, plus HNSW space info. */
  showIndexes: handleUnaryCall<ShowIndexesRequest, ShowIndexesResponse>;
  /** / Return server-wide storage and MVCC statistics. */
  showStats: handleUnaryCall<ShowStatsRequest, ShowStatsResponse>;
  /**
   * / Open a new multi-RPC transaction. Returns an opaque tx_id.
   * / Pass tx_id to Insert, Query, CypherWrite, or CypherQuery to join the
   * / transaction. Returns FAILED_PRECONDITION on a read replica.
   */
  beginTransaction: handleUnaryCall<BeginTransactionRequest, BeginTransactionResponse>;
  /**
   * / Commit an open transaction. Returns ABORTED on write-write conflict,
   * / NOT_FOUND if tx_id is unknown or has expired.
   * / Returns FAILED_PRECONDITION on a read replica.
   */
  commitTransaction: handleUnaryCall<CommitTransactionRequest, CommitTransactionResponse>;
  /**
   * / Roll back an open transaction, discarding all buffered writes.
   * / Returns NOT_FOUND if tx_id is unknown or has expired.
   * / Returns FAILED_PRECONDITION on a read replica.
   */
  rollbackTransaction: handleUnaryCall<RollbackTransactionRequest, RollbackTransactionResponse>;
  /**
   * / Return all RDF-star annotations on the edge identified by `edge_id`.
   * / Returns an empty list if the edge has no annotations or does not exist.
   */
  getEdgeAnnotations: handleUnaryCall<GetEdgeAnnotationsRequest, GetEdgeAnnotationsResponse>;
  /**
   * / Resolve the edge UUID(s) for a specific (subject, predicate, object) relation triple.
   * / Used by the SPARQL-star executor to look up edge IDs before fetching annotations.
   */
  getEdgeIdsByTriple: handleUnaryCall<GetEdgeIdsByTripleRequest, GetEdgeIdsByTripleResponse>;
  /**
   * / Add a new API key to the live key store. Takes effect immediately.
   * / Returns FAILED_PRECONDITION when the server was started without any
   * / keys (auth is disabled). Returns INVALID_ARGUMENT for an empty key.
   * / Returns FAILED_PRECONDITION on a read replica.
   */
  addApiKey: handleUnaryCall<AddApiKeyRequest, AddApiKeyResponse>;
  /**
   * / Remove an API key from the live key store. The caller should immediately
   * / stop using the revoked key. Returns FAILED_PRECONDITION when auth is
   * / disabled. Returns FAILED_PRECONDITION on a read replica.
   */
  revokeApiKey: handleUnaryCall<RevokeApiKeyRequest, RevokeApiKeyResponse>;
  /**
   * / List all configured API keys as masked prefixes (first 4 chars + "****").
   * / Never reveals full key values. Returns FAILED_PRECONDITION on a read
   * / replica.
   */
  listApiKeys: handleUnaryCall<ListApiKeysRequest, ListApiKeysResponse>;
  /**
   * / Grant a group access to a specific node or all nodes of a given type.
   * / Writes a HAS_ACCESS (or HAS_ACCESS_TYPE) triple and updates the
   * / in-memory access cache immediately.
   * / Returns FAILED_PRECONDITION on a read replica.
   */
  grantAccess: handleUnaryCall<GrantAccessRequest, GrantAccessResponse>;
  /**
   * / Revoke a group's access grant by closing the valid time of the
   * / HAS_ACCESS / HAS_ACCESS_TYPE triple and updating the cache.
   * / Returns FAILED_PRECONDITION on a read replica.
   */
  revokeAccess: handleUnaryCall<RevokeAccessRequest, RevokeAccessResponse>;
  /**
   * / Add a user to a group by writing a MEMBER_OF triple and updating
   * / the in-memory access cache.
   * / Returns FAILED_PRECONDITION on a read replica.
   */
  addUserToGroup: handleUnaryCall<AddUserToGroupRequest, AddUserToGroupResponse>;
  /**
   * / Return all node IDs and type grants accessible to a user, derived from
   * / their group memberships and HAS_ACCESS / HAS_ACCESS_TYPE triples.
   */
  getUserAccess: handleUnaryCall<GetUserAccessRequest, GetUserAccessResponse>;
  /**
   * / Return all historical versions of a node property, ordered newest-first
   * / by transaction time. Scans the full SPO column family without MVCC
   * / deduplication so every committed write is visible.
   */
  getPropertyHistory: handleUnaryCall<GetPropertyHistoryRequest, GetPropertyHistoryResponse>;
  /**
   * / Soft-delete triples for one or more subjects by closing their valid-time
   * / window. Each live triple (vt_end == END_OF_TIME) matching the subject (and
   * / optional predicate filter) receives a superseding entry with vt_end set to
   * / the requested timestamp (or server clock when vt_end == 0).
   * / Returns FAILED_PRECONDITION on a read replica.
   */
  deleteTriples: handleUnaryCall<DeleteTriplesRequest, DeleteTriplesResponse>;
  /**
   * / Run OWL 2 RL forward-chaining materialization to fixpoint.
   * /
   * / Derives new Relation triples according to the RDFS entailment and OWL
   * / property characteristic rules and writes them to the DRV column family.
   * / The DRV CF is separate from the base hexastore so derived triples can be
   * / wiped and rebuilt cleanly without touching user data.
   * /
   * / Returns FAILED_PRECONDITION on a read replica.
   */
  runMaterialization: handleUnaryCall<RunMaterializationRequest, RunMaterializationResponse>;
  /** / Which graphs inference reads schema axioms from. */
  getInferenceSettings: handleUnaryCall<GetInferenceSettingsRequest, InferenceSettings>;
  /**
   * / Change them (service calls, primary only); recomputes the inferred
   * / graphs and returns the run's statistics.
   */
  setInferenceSettings: handleUnaryCall<SetInferenceSettingsRequest, RunMaterializationResponse>;
}

